function maxPositions(a) {
  if (!Array.isArray(a) || !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use a dense array of safe integers");
  }
  if (a.length === 0) throw new RangeError("Use a nonempty list");
  let maximum = a[0], first = 0, last = 0;
  for (let i = 1; i < a.length; i++) {
    if (a[i] > maximum) {
      maximum = a[i]; first = i; last = i;
    } else if (a[i] === maximum) {
      last = i;
    }
  }
  return {maximum, first: first + 1, last: last + 1};
}

function pairMinMax(a) {
  if (!Array.isArray(a) || !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use a dense array of safe integers");
  }
  if (a.length === 0) throw new RangeError("Use a nonempty list");
  let min, max, i, comparisons = 0;
  if (a.length % 2 === 1) {
    min = max = a[0]; i = 1;
  } else {
    comparisons++;
    if (a[0] < a[1]) { min = a[0]; max = a[1]; }
    else { min = a[1]; max = a[0]; }
    i = 2;
  }
  for (; i < a.length; i += 2) {
    let low, high;
    comparisons++;
    if (a[i] < a[i + 1]) { low = a[i]; high = a[i + 1]; }
    else { low = a[i + 1]; high = a[i]; }
    comparisons++;
    if (low < min) min = low;
    comparisons++;
    if (high > max) max = high;
  }
  return {min, max, comparisons};
}
